    cases: [
      { id: 'c1', no: '01', kind: 'Case study', src: 'DuPont', brand: 'MOLYKOTE®', product: 'MOLYKOTE® G-5025 Grease', ind: 'Automotive · Brake systems', app: 'One-box EHB brake system', title: 'Silicone grease stabilises brake output pressure at −40 °C', customer: 'Bethel Automotive Safety Systems — brake system manufacturer, China', challenge: 'A competitor PAG lubricant could not hold output pressure at low temperature. The wire-control brake unit needed rubber and plastic compatibility through millions of load cycles from −40 to +120 °C.', solution: 'MOLYKOTE® G-5025 Grease, a silicone grease shown in lab testing to be compatible with EPDM and common plastics.', outcome: 'Lower starting and running torque at −40 °C, more stable output pressure across temperature, and reduced energy consumption. G-5025 was specified.', metrics: [{ k: 'Starting torque, −40 °C', a: '891.3', b: '110', u: 'mN·m' }, { k: 'Running torque, 20 min', a: '169.8', b: '23.2', u: 'mN·m' }], specs: ['Silicone', '−40 → 120 °C', 'EPDM compatible'], href: 'https://www.dupont.com/knowledge/molykote-g-5025-grease-case-study.html', pdf: 'https://www.dupont.com/content/dam/dupont/amer/us/en/Molykote/public/documents/en/MOLYKOTE_G-5025_Grease_Case_Study_02-0010-01-AGP0921_16984.pdf' },
      { id: 'c2', no: '02', kind: 'Case study', src: 'DuPont', brand: 'MOLYKOTE®', product: 'MOLYKOTE® M-77 Paste', ind: 'Automotive · EV battery', app: 'Cell-to-pack battery cooling plate', title: 'Silicone paste removes screw noise in an EV battery pack', customer: 'Battery supplier to an automotive manufacturer, China', challenge: 'When the liquid cooling system started, the sudden temperature change made the screws joining the cooling plate to the pack creak — an NVH problem. The lubricant also had to provide insulation.', solution: 'MOLYKOTE® M-77 Paste — silicone-based, with MoS₂ solid lubricant — tested against other lubricant technologies.', outcome: 'Of the technologies tested, only M-77 Paste both reduced the noise and met the insulation requirement.', metrics: [], specs: ['Silicone', 'MoS₂ solid lubricant', 'NVH'], href: 'https://www.dupont.com/knowledge/molykote-m-77-paste-case-study.html', pdf: 'https://www.dupont.com/content/dam/dupont/amer/us/en/Molykote/public/documents/en/16520D_Molykote_M-77_CaseStudy_v2.pdf' },
      { id: 'c3', no: '03', kind: 'Application note', src: 'Dow', brand: 'DOWSIL™', product: 'DOWSIL™ TC-6032 Thermally Conductive Encapsulant', ind: 'E-mobility · Power electronics', app: 'On-board chargers, DC/DC converters, inductors', title: 'Encapsulating EV power electronics while moving heat out', customer: 'EV power electronics — on-board chargers (OBC), DC/DC converters, inductors and transformers', challenge: 'Power modules run hot and at high voltage, in conditions that include salt spray, shock and vibration. Components need to be protected and kept cool for the vehicle\'s life.', solution: 'DOWSIL™ TC-6032 — a two-part, heat-cure, thermally conductive silicone encapsulant with good flowability.', outcome: 'Encapsulates the assembly and maintains a thermal path to dissipate heat, supporting long-term reliability.', metrics: [], specs: ['3.2 W/m·K', 'Two-part', 'Heat cure'], href: 'https://www.dow.com/en-us/market/mkt-mobility/sub-mobility-electronics/app-mobility-elec-power-electronic.html', pdf: '' },
      { id: 'c4', no: '04', kind: 'Application note', src: 'Dow', brand: 'DOWSIL™', product: 'DOWSIL™ CC-8030 / CC-8000 Series Conformal Coatings', ind: 'Automotive · ADAS electronics', app: 'ADAS and automotive PCBA protection', title: 'Fast-curing silicone protection for ADAS circuit boards', customer: 'ADAS and automotive electronics — printed circuit board assemblies (PCBA)', challenge: 'Boards with sensitive and fine-pitch components need protection from moisture, contaminants and thermal cycling, without slowing a high-volume line.', solution: 'DOWSIL™ CC-8000 Series UV + moisture dual-cure silicone coatings: CC-8030 for spray, CC-8033 for spray or needle, CC-8036 for needle dispense (dam and fill).', outcome: 'Primary UV cure in seconds, with secondary moisture cure in shadowed areas under components. No added solvents; UL 94 V-0.', metrics: [], specs: ['UV + moisture cure', 'No added solvents', 'UL 94 V-0'], href: 'https://www.dow.com/en-us/pdp.dowsil-cc-8030-uv-and-dual-moisture-cure-conformal-coating.495453z.html', pdf: '' }
    ],
